/**
 * Catálogo CIE-10 para el buscador de diagnósticos del examen ocupacional.
 *
 * Códigos en formato RIPS (4 caracteres, sin punto: "M545", no "M54.5"), que es
 * como los escribe el equipo médico y como los exige el RIPS colombiano.
 *
 * Fuente: unión deduplicada de tres orígenes — el catálogo del repo RIPS
 * (capítulos I–X) y dos volcados de consultas reales de datos.gov.co (2024
 * nacional por género, y Tuluá 2019+), que aportan los capítulos XI–XXII que al
 * primero le faltaban. Son 4784 códigos: no es el CIE-10 completo (~12.000),
 * pero cubre todo lo que se ha usado de verdad en consulta, incluidos los 300+
 * osteomusculares (M) que un examen de Bodytech más necesita. Si hace falta el
 * catálogo oficial completo, se reemplaza este archivo: el componente sólo
 * espera `{ codigo, nombre }[]`.
 *
 * Se importa con `import()` dinámico desde `Cie10Field`: son ~300 KB que no
 * tiene sentido pagar hasta que alguien abra el modal de Diagnósticos.
 */
export interface Cie10Entry {
  codigo: string;
  nombre: string;
}

